#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricResistance; 8] = [
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Ohm),
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Nanoohm),
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Microohm),
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Milliohm),
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Kiloohm),
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Megaohm),
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Gigaohm),
        ElectricResistance::const_new(1234.5, ElectricResistanceUnit::Teraohm),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ElectricResistanceUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricResistance::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricResistanceUnit::ALL {
            assert_eq!(
                ElectricResistance::const_new(v, unit).as_base().to_bits(),
                ElectricResistance::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricResistance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricResistance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricResistanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricResistance::from_base(0.0).auto_unit().unit,
        ElectricResistanceUnit::Ohm
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Ω".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Ohm)
    );
    assert_eq!(
        format!("2.5 {}", "Ω").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(2.5, ElectricResistanceUnit::Ohm))
    );
    assert_eq!(
        "nΩ".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Nanoohm)
    );
    assert_eq!(
        format!("2.5 {}", "nΩ").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(
            2.5,
            ElectricResistanceUnit::Nanoohm
        ))
    );
    assert_eq!(
        "µΩ".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Microohm)
    );
    assert_eq!(
        format!("2.5 {}", "µΩ").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(
            2.5,
            ElectricResistanceUnit::Microohm
        ))
    );
    assert_eq!(
        "mΩ".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Milliohm)
    );
    assert_eq!(
        format!("2.5 {}", "mΩ").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(
            2.5,
            ElectricResistanceUnit::Milliohm
        ))
    );
    assert_eq!(
        "kΩ".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Kiloohm)
    );
    assert_eq!(
        format!("2.5 {}", "kΩ").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(
            2.5,
            ElectricResistanceUnit::Kiloohm
        ))
    );
    assert_eq!(
        "MΩ".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Megaohm)
    );
    assert_eq!(
        format!("2.5 {}", "MΩ").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(
            2.5,
            ElectricResistanceUnit::Megaohm
        ))
    );
    assert_eq!(
        "GΩ".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Gigaohm)
    );
    assert_eq!(
        format!("2.5 {}", "GΩ").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(
            2.5,
            ElectricResistanceUnit::Gigaohm
        ))
    );
    assert_eq!(
        "TΩ".parse::<ElectricResistanceUnit>(),
        Ok(ElectricResistanceUnit::Teraohm)
    );
    assert_eq!(
        format!("2.5 {}", "TΩ").parse::<ElectricResistance>(),
        Ok(ElectricResistance::new(
            2.5,
            ElectricResistanceUnit::Teraohm
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricResistance>(),
        Err(ParseError::UnknownUnit)
    );
}

